import sqlite3

def siapkan(con):
    con.execute("PRAGMA foreign_keys = ON")
    con.executescript("""
    CREATE TABLE barang (id INTEGER PRIMARY KEY,
      stok INTEGER NOT NULL CHECK(typeof(stok) = 'integer' AND stok >= 0));
    CREATE TABLE permintaan (
      kode TEXT PRIMARY KEY NOT NULL,
      barang_id INTEGER NOT NULL REFERENCES barang(id),
      jumlah INTEGER NOT NULL CHECK(typeof(jumlah) = 'integer' AND jumlah > 0)
    );
    """)

def reservasi(con, kode, barang_id, jumlah):
    if not isinstance(kode, str) or not kode.strip():
        raise ValueError("Kode permintaan wajib diisi")
    if type(barang_id) is not int or barang_id <= 0 or type(jumlah) is not int or jumlah <= 0:
        raise ValueError("Id dan jumlah harus integer positif")
    kode = kode.strip()
    con.execute("BEGIN IMMEDIATE")
    try:
        lama = con.execute("SELECT barang_id, jumlah FROM permintaan WHERE kode = ?", (kode,)).fetchone()
        if lama is not None:
            if lama != (barang_id, jumlah):
                raise ValueError("Kode sudah dipakai dengan isi berbeda")
            con.execute("COMMIT")
            return False
        cur = con.execute("UPDATE barang SET stok = stok - ? WHERE id = ? AND stok >= ?",
                          (jumlah, barang_id, jumlah))
        if cur.rowcount != 1:
            raise ValueError("Barang tidak ada atau stok tidak cukup")
        con.execute("INSERT INTO permintaan (kode, barang_id, jumlah) VALUES (?, ?, ?)",
                    (kode, barang_id, jumlah))
        con.execute("COMMIT")
        return True
    except Exception:
        con.execute("ROLLBACK")
        raise

def main():
    con = sqlite3.connect(":memory:", isolation_level=None)
    try:
        siapkan(con)
        con.execute("INSERT INTO barang VALUES (1, 5)")
        print("Baru:", reservasi(con, "R01", 1, 2))
        print("Ulang sama:", reservasi(con, "R01", 1, 2))
        try:
            reservasi(con, "R01", 1, 3)
        except ValueError as error:
            print("Ditolak:", error)
        try:
            reservasi(con, "R02", 1, 4)
        except ValueError as error:
            print("Ditolak:", error)
        print("Stok akhir:", con.execute("SELECT stok FROM barang WHERE id = 1").fetchone()[0])
        print("Operasi tercatat:", con.execute("SELECT COUNT(*) FROM permintaan").fetchone()[0])
    finally:
        con.close()

if __name__ == "__main__":
    main()

